# Fits the first-guess tables from build/guess/data_<cards>.bin (see dump.cpp) and writes src/guess_tables.inc.
# Run from the repository root: python3 tools/guess/export.py (needs numpy and scipy).
import numpy as np, sys
sys.path.insert(0,__import__('os').path.dirname(__import__('os').path.abspath(__file__)))
from fit import load, POP, cost
from fit2 import featsC, designC
from scipy.sparse.linalg import lsqr
REV=np.array([int('{:04b}'.format(i)[::-1],2) for i in range(16)])
CAP=3; NK=16*(CAP+1)**4
out=['// Generated by tools/guess/export.py: weights (in 1/64 trick) of the first-guess model.\n// [cards - 4][no trumps][0..4095 side suit keys, 4096..8191 trump suit keys, 8192..8220 trump length difference + 14]\n','static const int16_t kGuessW[4][2][%d] = {\n'%(2*NK+29)]
for n in (4,5,6,7):
    h,trump,leader,v=load(n); N=len(v); vl=np.where(leader&1,n-v,v)
    key,ln=featsC(h,leader,CAP)
    key=(key&~15)|REV[key&15]          # highest card in bit 3
    X=designC(key,ln,trump,NK)
    out.append(' {\n')
    est=np.zeros(N)
    for nt in (0,1):
        m=((trump==4)==bool(nt))
        w=lsqr(X[m],vl[m].astype(float),damp=1.0,iter_lim=500)[0]
        q=np.clip(np.rint(w*64),-32000,32000).astype(int)
        est[m]=(X[m]@q)
        out.append('  {'+','.join(map(str,q))+'},\n')
    out.append(' },\n')
    ens=np.where(leader&1,n*64-est,est)
    t=np.clip(np.floor((ens+64)/64),1,n).astype(int)
    print('n',n,'questions (in-sample, quantized) %.4f'%cost(t,v,n).mean())
out.append('};\n')
open('src/guess_tables.inc','w').write(''.join(out))
